CREATE VIEW dbo.MUPanicFracturaLaureatesV34 AS
SELECT r.CharacterName AS CharacterName,r.Family AS Family,g.Contribution AS Contribution,MAX(r.DistinctionUntilUnix) AS DistinctionUntilUnix FROM [MuOnline43].[dbo].[MUPanicWeekClaimsV31] r JOIN [MuOnline43].[dbo].[Character] c ON c.Name=r.CharacterName AND c.AccountID=r.AccountID JOIN [MuOnline43].[dbo].[Gens_Rank] g ON g.Name=c.Name AND g.Family=r.Family WHERE r.Result='W' AND r.State='DELIVERED' AND r.DistinctionUntilUnix>DATEDIFF(second,CONVERT(datetime2,'19700101',112),SYSUTCDATETIME()) GROUP BY r.CharacterName,r.Family,g.Contribution;
